<script setup>import {state,actions,displayTime} from '../../domain/prototypeStore.js';import {ref} from 'vue';const msg=ref('');const scan=v=>{const r=actions.checkin(v);msg.value=r.message}</script>
<template><section class="h5-page"><div class="h5-module-hero"><span>卡</span><h2>扫码打卡</h2><p>{{state.checkinRules.point}} · {{state.checkinRules.time}}</p></div><p v-if="msg" class="action-message">{{msg}}</p><div class="qr-placeholder">演示二维码</div><div class="button-row"><button class="primary-button active" @click="scan(true)">确认扫码打卡</button><button class="secondary-button" @click="scan(false)">模拟超出范围</button></div><article class="h5-card"><h3>最近记录</h3><p v-for="r in state.checkins.slice(0,3)" :key="r.id">{{displayTime(r.time)}} · {{r.status}} · {{r.reason}}</p></article></section></template>
